// Background sync for offline data (when implemented)
self.addEventListener('sync', event => {
  if (event.tag === 'sync-forecast') {
    event.waitUntil(syncForecastData());
  }
});

// Push notifications (when implemented)
self.addEventListener('push', event => {
  if (event.data) {
    const data = event.data.json();
    event.waitUntil(
      self.registration.showNotification(data.title, {
        body: data.body,
        icon: '/icon-192.png',
        badge: '/badge-72.png',
        tag: data.tag,
      })
    );
  }
});

// Notification click handler
self.addEventListener('notificationclick', event => {
  event.notification.close();
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(clientList => {
      for (const client of clientList) {
        if (client.url === event.notification.data?.url && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(event.notification.data?.url || '/');
      }
    })
  );
});

// Periodic background sync for forecast updates (when implemented)
self.addEventListener('periodicsync', event => {
  if (event.tag === 'update-forecast') {
    event.waitUntil(updateForecastCache());
  }
});

// Message handler for cache management
self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
  if (event.data && event.data.type === 'CLEAR_CACHE') {
    event.waitUntil(clearAllCaches());
  }
  if (event.data && event.data.type === 'GET_CACHE_STATUS') {
    event.ports[0].postMessage(getCacheStatus());
  }
});

// Helper functions
async function syncForecastData() {
  // Implementation for background sync of forecast data
  const cache = await caches.open('open-meteo-forecast');
  const keys = await cache.keys();
  for (const key of keys) {
    try {
      await cache.add(key);
    } catch {
      console.log('Sync failed for', key.url);
    }
  }
}

async function updateForecastCache() {
  // Implementation for periodic forecast updates
  await caches.open('open-meteo-forecast');
  // Could pre-fetch for user's saved locations
}

async function clearAllCaches() {
  const cacheNames = await caches.keys();
  await Promise.all(cacheNames.map(name => caches.delete(name)));
}

async function getCacheStatus() {
  const cacheNames = await caches.keys();
  const status = {};
  for (const name of cacheNames) {
    const cache = await caches.open(name);
    const keys = await cache.keys();
    status[name] = { entries: keys.length };
  }
  return status;
}

// Version info for debugging
self.addEventListener('install', () => {
  console.log('[SW] Installing service worker v' + (self.registration?.scope || 'unknown'));
});

self.addEventListener('activate', () => {
  console.log('[SW] Activating service worker');
});